import json, os, sys, urllib.request, urllib.parse
keys = [k.strip() for k in os.environ['OPENALEX_API_KEYS'].split(',') if k.strip()]
def get(url):
    d = {}
    for k in keys:
        u = url + ('&' if '?' in url else '?') + 'api_key=' + k
        try:
            d = json.load(urllib.request.urlopen(u, timeout=60))
        except urllib.error.HTTPError as e:
            d = json.loads(e.read() or b'{}')
        if 'error' not in d: return d
    raise SystemExit('all keys exhausted: ' + str(d)[:200])
def inv(ab):
    if not ab: return ''
    pos = sorted((p, w) for w, ps in ab.items() for p in ps)
    return ' '.join(w for p, w in pos)
def show(d, abstracts):
    for w in d['results']:
        src = ((w.get('primary_location') or {}).get('source') or {}).get('display_name')
        print(w['publication_year'],'|',w['doi'],'|',w['id'].split('/')[-1],'|',w['title'],'|',src,'|',', '.join(a['author']['display_name'] for a in w['authorships'][:4]),'| cites',w['cited_by_count'])
        if abstracts: print('   ABS:', inv(w.get('abstract_inverted_index'))[:700])
mode, arg = sys.argv[1], sys.argv[2]
ab = '--abs' in sys.argv
if mode == 'cites':
    url = f'https://api.openalex.org/works?filter=cites:{arg},publication_year:2022-2026&per_page=200'
    d = get(url); print('COUNT', d['meta']['count']); show(d, ab)
elif mode == 'search':
    url = f'https://api.openalex.org/works?filter=title_and_abstract.search:{urllib.parse.quote(arg)},publication_year:2022-2026&per_page=50&sort=relevance_score:desc'
    d = get(url); print('COUNT', d['meta']['count']); show(d, ab)
elif mode == 'doi':
    w = get(f'https://api.openalex.org/works/doi:{arg}'); show({'results':[w]}, True)
EOF
